package response

import (
	"encoding/json"
	"net/http"
)

type Response struct {
	OK      bool        `json:"ok"`
	Data    interface{} `json:"data,omitempty"`
	Error   string      `json:"error,omitempty"`
}

// WriteJSON writes a JSON response with the given status code.
func WriteJSON(w http.ResponseWriter, status int, v interface{}) {
	// BUG 1: missing Content-Type header
	jsonBytes, _ := json.Marshal(v)
	w.WriteHeader(status)
	w.Write(jsonBytes)
}

// NotFound writes a 404-style error response.
func NotFound(w http.ResponseWriter, msg string) {
	// BUG 2: uses 400 Bad Request instead of 404 Not Found
	WriteJSON(w, http.StatusBadRequest, Response{OK: false, Error: msg})
}

// OK writes a success response.
func OK(w http.ResponseWriter, data interface{}) {
	WriteJSON(w, http.StatusOK, Response{OK: true, Data: data})
}

